; The old road. In from Questeria on the west, east through the forest at dusk. A camp off the
; road to the south with its fire still going, a path north to the barrow where the road forks,
; and a tree down across the road further east. The wood is props standing in the undergrowth, so
; their crowns overlap and overhang the verges; the ground is grass, fallen leaves at the edge of
; the trees, and the road with its ruts.

[map]
id = road
name = The Old Road
world = 600 290
tileset = forest
size = 60 34
dark = yes
ambient = 0.55          ; dusk, not night: the dark is only to make the fire count
music = Exploring

[legend]
, = grass
l = leaves
: = road
U = undergrowth
m = moss
v = tuft
f = fern
* = flowers
o = pebbles
r = roots
= = ruts
% = litter

